BASE=Path(__file__).resolve().parent;ROOT=BASE.parents[2];OUT=BASE/'textures';OUT.mkdir(exist_ok=True);SOURCE=ROOT/'src/cocos/assets/resources/actors/native-shared/textures';records=[]
