source=ROOT/'src/cocos/assets/resources/actors/player-aim-v1/cloth-burgundy.png';original=Image.open(source).convert('RGBA').resize((1024,1024),Image.Resampling.LANCZOS);cloud=Image.open(BASE/'cloth-cloud.png').convert('RGBA').resize(original.size,Image.Resampling.LANCZOS);native=Image.open(SOURCE/'eb115041165b2ae8-T_Ranger_BaseColor.png').convert('RGB');hsv=np.asarray(native.convert('HSV'));fabric=(hsv[:,:,0]>55)&(hsv[:,:,0]<150)&(hsv[:,:,1]>25);mask=np.array(Image.fromarray(np.uint8(fabric)*255).resize(original.size,Image.Resampling.NEAREST)).astype(float)/255;mask=gaussian_filter(mask,.65);mask[mask<.05]=0;mask=np.clip(mask,0,1);a=np.array(original).copy();candidate=np.array(cloud);a[:,:,:3]=np.uint8(a[:,:,:3]*(1-mask[:,:,None])+candidate[:,:,:3]*mask[:,:,None]);Image.fromarray(a).save(OUT/'cloth-burgundy.png');outside=mask==0;assert np.array_equal(a[outside],np.array(original)[outside]);Image.fromarray(np.uint8(mask*255)).save(BASE/'fabric-composite-mask.png');records.append({'source':source.relative_to(ROOT).as_posix(),'cloudOutput':'cloth-cloud.png','generatedSize':Image.open(BASE/'cloth-cloud.png').size,'runtimeSize':[1024,1024],'outsideFabricMaskPixelsUnchanged':True,'method':'Cloud OpenAI image_gen embroidery; Pillow/SciPy UV-size normalization and fabric-only composite; leather/hardware/padding and alpha protected'})
